package com.receiptledger.v1.review;

import com.receiptledger.v1.item.*;import com.receiptledger.v1.persistence.*;import com.receiptledger.v1.validation.*;import java.util.*;

public final class ReceiptReviewEngine {
    public ReceiptRecord apply(ReceiptRecord base,String purchaseDate,Long printedTotal,Long discountSum,List<ReviewItemInput> edits){return apply(base,base==null?null:base.storeName,purchaseDate,printedTotal,discountSum,edits);}
    public ReceiptRecord apply(ReceiptRecord base,String storeName,String purchaseDate,Long printedTotal,Long discountSum,List<ReviewItemInput> edits){if(base==null)throw new IllegalArgumentException("base");if(edits==null||edits.size()!=base.items.size())throw new IllegalArgumentException("item count changed");String normalizedStore=storeName==null?null:storeName.trim();if(normalizedStore!=null&&normalizedStore.isEmpty())normalizedStore=null;if(normalizedStore!=null&&normalizedStore.length()>80)throw new IllegalArgumentException("매장명은 80자 이하여야 합니다.");List<PersistedItem> out=new ArrayList<>();List<String> issues=new ArrayList<>();boolean changed=!Objects.equals(base.storeName,normalizedStore)||!Objects.equals(base.purchaseDate,purchaseDate)||!Objects.equals(base.printedTotal,printedTotal)||!Objects.equals(base.discountSum,discountSum);if(!Objects.equals(base.storeName,normalizedStore))issues.add("USER_EDITED_STORE");if(!Objects.equals(base.purchaseDate,purchaseDate))issues.add("USER_EDITED_DATE");if(!Objects.equals(base.printedTotal,printedTotal))issues.add("USER_EDITED_PRINTED_TOTAL");if(!Objects.equals(base.discountSum,discountSum))issues.add("USER_EDITED_DISCOUNT_SUM");long itemSum=0;boolean missingAmount=false,arithmeticMismatch=false,partial=false;
        for(int i=0;i<edits.size();i++){PersistedItem old=base.items.get(i);ReviewItemInput e=edits.get(i);String name=e.name==null?"":e.name.trim();if(name.isEmpty())throw new IllegalArgumentException("상품명 "+(i+1)+"이 비어 있습니다.");if(e.quantity!=null&&e.quantity<=0)throw new IllegalArgumentException("수량은 1 이상이어야 합니다.");if(e.unitPrice!=null&&e.unitPrice<0)throw new IllegalArgumentException("단가는 0 이상이어야 합니다.");if(e.lineAmount!=null&&e.lineAmount<0)throw new IllegalArgumentException("상품 행금액은 0 이상이어야 합니다.");boolean nameChanged=!old.name.equals(name),qChanged=!Objects.equals(old.quantity,e.quantity),uChanged=!Objects.equals(old.unitPrice,e.unitPrice),aChanged=!Objects.equals(old.lineAmount,e.lineAmount);boolean itemChanged=nameChanged||qChanged||uChanged||aChanged;if(itemChanged){changed=true;issues.add("USER_EDITED_ITEM:"+(i+1));}ValueOrigin qo=qChanged?ValueOrigin.USER_EDITED:old.quantityOrigin,uo=uChanged?ValueOrigin.USER_EDITED:old.unitPriceOrigin,ao=aChanged?ValueOrigin.USER_EDITED:old.lineAmountOrigin;ItemResolution resolution;String reason=itemChanged?"USER_REVIEW_EDIT":old.reason;if(e.lineAmount==null){missingAmount=true;partial=true;resolution=ItemResolution.PARTIAL;issues.add("ITEM_LINE_AMOUNT_MISSING:"+(i+1));}else{itemSum+=e.lineAmount;if(e.quantity!=null&&e.unitPrice!=null){long expected=(long)e.quantity*e.unitPrice;if(expected==e.lineAmount)resolution=ItemResolution.EXACT;else{resolution=ItemResolution.PARTIAL;arithmeticMismatch=true;issues.add("ITEM_ARITHMETIC_MISMATCH:"+(i+1)+":"+expected+"!="+e.lineAmount);}}else{resolution=ItemResolution.PARTIAL;partial=true;issues.add("ITEM_TUPLE_PARTIAL:"+(i+1));}}out.add(new PersistedItem(i,old.rowIndex,name,e.quantity,e.unitPrice,e.lineAmount,qo,uo,ao,resolution,reason));}
        Long normalizedDiscount=discountSum==null?0L:discountSum;Long computed=missingAmount?null:itemSum+normalizedDiscount;Long diff=(computed==null||printedTotal==null)?null:computed-printedTotal;ValidationStatus status;if(computed==null||printedTotal==null)status=ValidationStatus.INCOMPLETE;else if(arithmeticMismatch||diff!=0)status=ValidationStatus.MISMATCH;else if(changed||partial)status=ValidationStatus.PASS_WITH_WARNINGS;else status=ValidationStatus.PASS;if(status==ValidationStatus.MISMATCH&&diff!=null&&diff!=0)issues.add("RECEIPT_TOTAL_MISMATCH:"+diff);if(status==ValidationStatus.INCOMPLETE)issues.add("REVIEW_INCOMPLETE");return new ReceiptRecord(base.id,base.createdAtMillis,purchaseDate,normalizedStore,base.rawOcrText,printedTotal,missingAmount?null:itemSum,normalizedDiscount,computed,diff,status,base.sourceWidth,base.sourceHeight,base.perspectiveCorrected,issues,out);}
}
